// Writes supabase/apply-all.sql: every migration in order, then the seed.
// Owners paste that one file into the Supabase SQL editor on a new project (docs/setup/01-supabase.md).
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HEADER = `-- Gangasagar database: all migrations, then the seed.
-- Generated by \`npm run db:combine\` from supabase/migrations and supabase/seed.sql. Do not edit by hand.
-- Run it once, on a new Supabase project, in the SQL editor.
`;

/** @param {string} root repository root */
export function combineMigrations(root) {
  const dir = path.join(root, 'supabase', 'migrations');
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('.sql'))
    .sort()
    .map((f) => path.join(dir, f));
  files.push(path.join(root, 'supabase', 'seed.sql'));
  const parts = files.map((f) => `-- ==== ${path.basename(f)} ====\n\n${readFileSync(f, 'utf8').trim()}\n`);
  return `${HEADER}\n${parts.join('\n')}`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
  const out = path.join(root, 'supabase', 'apply-all.sql');
  writeFileSync(out, combineMigrations(root));
  console.log(`wrote ${path.relative(root, out)}`);
}
